  readonly strings: AppStrings;
  readonly providers: readonly (Provider | EnvironmentProviders)[];
  /** `{property: client class}` -- each API client under the property the
   * app's classes name it by. */
  readonly api: Readonly<A>;
  readonly appState: Type<S>;
  /** The argument a paginated client method takes its page position as. A
   * call names its endpoint by the arguments the DSL passes, never by the
   * position a pager adds. The rows a test answers with are one page: the
   * envelope answers them as its first page (`total` their count), and every
   * later position is an empty page of the same total. */
  readonly pagePosition: string;
